from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**15
        dp_prev = [[NEG_INF]*3 for _ in range(n)]
        # Initialize first cell
        c = coins[0][0]
        if c >= 0:
            dp_prev[0][0] = c
        else:
            dp_prev[0][0] = c  # negative value
            if m > 1 or n > 1:
                dp_prev[0][1] = 0  # neutralize at start if negative
        # Process first row
        for j in range(1, n):
            cur = [NEG_INF]*3
            c = coins[0][j]
            val = c if c >= 0 else -abs(c)
            for k in range(3):
                if dp_prev[j-1][k] != NEG_INF:
                    # no neutralization
                    cur[k] = max(cur[k], dp_prev[j-1][k] + val)
                    # use neutralization if possible
                    if c < 0 and k < 2:
                        cur[k+1] = max(cur[k+1], dp_prev[j-1][k])
            dp_prev[j] = cur
        # Process remaining rows
        for i in range(1, m):
            cur_row = [[NEG_INF]*3 for _ in range(n)]
            # first column of current row
            c = coins[i][0]
            val = c if c >= 0 else -abs(c)
            for k in range(3):
                if dp_prev[0][k] != NEG_INF:
                    cur_row[0][k] = max(cur_row[0][k], dp_prev[0][k] + val)
                    if c < 0 and k < 2:
                        cur_row[0][k+1] = max(cur_row[0][k+1], dp_prev[0][k])
            # rest of columns
            for j in range(1, n):
                c = coins[i][j]
                val = c if c >= 0 else -abs(c)
                best = [NEG_INF]*3
                # from top
                for k in range(3):
                    if dp_prev[j][k] != NEG_INF:
                        best[k] = max(best[k], dp_prev[j][k] + val)
                        if c < 0 and k < 2:
                            best[k+1] = max(best[k+1], dp_prev[j][k])
                # from left
                for k in range(3):
                    if cur_row[j-1][k] != NEG_INF:
                        best[k] = max(best[k], cur_row[j-1][k] + val)
                        if c < 0 and k < 2:
                            best[k+1] = max(best[k+1], cur_row[j-1][k])
                cur_row[j] = best
            dp_prev = cur_row
        return max(dp_prev[n-1])
