class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        from bisect import bisect_left, bisect_right

        def kmp_occurrences(text: str, pat: str):
            n, m = len(text), len(pat)
            if m == 0:
                return []
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pat[i] == pat[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length != 0:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1
            res = []
            i = j = 0
            while i < n:
                if text[i] == pat[j]:
                    i += 1
                    j += 1
                    if j == m:
                        res.append(i - m)
                        j = lps[j - 1]
                else:
                    if j != 0:
                        j = lps[j - 1]
                    else:
                        i += 1
            return res

        # split pattern
        first = p.find('*')
        second = p.rfind('*')
        A = p[:first]
        B = p[first+1:second]
        C = p[second+1:]
        lenA, lenB, lenC = len(A), len(B), len(C)
        n = len(s)

        # early trivial case
        if lenA == 0 and lenB == 0 and lenC == 0:
            return 0

        # find occurrences
        Apos = kmp_occurrences(s, A) if lenA > 0 else []
        Bpos = kmp_occurrences(s, B) if lenB > 0 else list(range(n+1))
        Cpos = kmp_occurrences(s, C) if lenC > 0 else []

        INF = 10**18
        best = INF

        for posB in Bpos:
            # choose posA
            if lenA > 0:
                targetA = posB - lenA
                idxA = bisect_right(Apos, targetA) - 1
                if idxA < 0:
                    continue
                posA = Apos[idxA]
            else:
                posA = posB

            # choose posC
            if lenC > 0:
                targetC = posB + lenB
                idxC = bisect_left(Cpos, targetC)
                if idxC == len(Cpos):
                    continue
                posC = Cpos[idxC]
            else:
                posC = posB + lenB

            length = (posC + lenC) - posA
            if length < best:
                best = length

        return -1 if best == INF else best
