class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            d = int(s[i])
            if d == 0:
                continue
            cur = 0
            mult = 1
            # consider at most 10 digits (since d <= 9, 10^10 > 1e9, safe bound)
            for j in range(i, max(i-9, -1), -1):
                digit = int(s[j])
                cur = (digit * mult + cur) % d
                if cur == 0:
                    ans += 1
                mult = (mult * 10) % d
        return ans
