class Solution:
    def largestInteger(self, nums: list[int], k: int) -> int:
        n = len(nums)
        if k > n:  # invalid, but per constraints won't happen
            return -1
        freq = {}
        for i in range(n - k + 1):
            window_set = set(nums[i:i+k])
            for val in window_set:
                freq[val] = freq.get(val, 0) + 1
        candidates = [val for val, cnt in freq.items() if cnt == 1]
        return max(candidates) if candidates else -1
