class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        idx = 0
        for r, row in enumerate(grid):
            if r % 2 == 0:
                cols = range(len(row))
            else:
                cols = range(len(row)-1, -1, -1)
            for c in cols:
                if idx % 2 == 0:
                    result.append(row[c])
                idx += 1
        return result
