class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        for i in range(n - k + 1):
            sub = s[i:i + k]
            if len(set(sub)) != 1:
                continue
            char = sub[0]
            before_ok = (i == 0) or (s[i - 1] != char)
            after_ok = (i + k == n) or (s[i + k] != char)
            if before_ok and after_ok:
                return True
        return False
