class Solution:
    def minMaxSums(self, nums: list[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        t = k - 2
        # Precompute f[d] = sum_{i=0}^{min(d,t)} C(d,i)
        f = []
        if t >= 0 and n >= 2:
            max_d = n - 2
            C = [0] * (t + 1)
            C[0] = 1
            f.append(1)  # d = 0
            for d in range(1, max_d + 1):
                up = min(t, d)
                for i in range(up, 0, -1):
                    C[i] = (C[i] + C[i-1]) % MOD
                # C[0] remains 1
                f.append(sum(C[:t+1]) % MOD)
        # prefix sums of f
        prefix_f = [0] * n
        for i in range(1, n):
            if i-1 < len(f):
                prefix_f[i] = (prefix_f[i-1] + f[i-1]) % MOD
            else:
                prefix_f[i] = prefix_f[i-1]
        total_f = prefix_f[n-1] if n >= 1 else 0
        ans = 0
        if k >= 1:
            for v in nums:
                ans = (ans + 2 * v) % MOD
        if t >= 0 and n >= 2:
            # r-sum
            for r in range(n):
                ans = (ans + nums[r] * prefix_f[r]) % MOD
            # l-sum
            for l in range(n):
                val = (total_f - prefix_f[l]) % MOD
                ans = (ans + nums[l] * val) % MOD
        return ans % MOD
