from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Prepare sorted unique weights
        weights = sorted({w for _, _, w in edges})
        if not weights:
            return -1

        # Helper to test feasibility for a given weight limit
        def feasible(limit: int) -> bool:
            rev_adj = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= limit:
                    rev_adj[b].append(a)  # reversed edge
            vis = [False] * n
            q = deque([0])
            vis[0] = True
            cnt = 1
            while q:
                u = q.popleft()
                for v in rev_adj[u]:
                    if not vis[v]:
                        vis[v] = True
                        cnt += 1
                        q.append(v)
                        if cnt == n:
                            return True
            return cnt == n

        # Binary search over weights
        lo, hi = 0, len(weights) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
