        n = len(nums)
        total = 0
        for i in range(n):
            good = True
            left = i - k
            right = i + k
            if left >= 0 and nums[i] <= nums[left]:
                good = False
            if right < n and nums[i] <= nums[right]:
                good = False
            if good:
                total += nums[i]
