from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(1, n + 1):
            pref[i] = pref[i - 1] + nums[i - 1]

        NEG = -10**18
        dp = [[NEG] * (n + 1) for _ in range(k + 1)]
        for i in range(n + 1):
            dp[0][i] = 0

        for seg in range(1, k + 1):
            best = NEG
            for i in range(1, n + 1):
                if i >= m:
                    s = i - m + 1
                    val = dp[seg - 1][s - 1] - pref[s - 1]
                    if val > best:
                        best = val
                best_end = pref[i] + best if best != NEG else NEG
                prev = dp[seg][i - 1]
                dp[seg][i] = best_end if best_end > prev else prev

        return dp[k][n]
