class Solution:
    def lenOfVDiagonal(self, grid):
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        dx = [d[0] for d in dirs]
        dy = [d[1] for d in dirs]

        # DP arrays for start with 1,2,0
        dp1 = [[[0] * m for _ in range(n)] for _ in range(4)]
        dp2 = [[[0] * m for _ in range(n)] for _ in range(4)]
        dp0 = [[[0] * m for _ in range(n)] for _ in range(4)]

        # Order for reverse traversal (next cell processed first)
        rev_order = [
            [(i, j) for i in range(n-1, -1, -1) for j in range(m-1, -1, -1)],          # d=0
            [(i, j) for i in range(n-1, -1, -1) for j in range(m)],                    # d=1
            [(i, j) for i in range(n) for j in range(m-1, -1, -1)],                    # d=2
            [(i, j) for i in range(n) for j in range(m)],                              # d=3
        ]

        for d in range(4):
            for i, j in rev_order[d]:
                ni, nj = i + dx[d], j + dy[d]
                if ni < 0 or ni >= n or nj < 0 or nj >= m:
                    # no next cell
                    if grid[i][j] == 1:
                        dp1[d][i][j] = 1
                    if grid[i][j] == 2:
                        dp2[d][i][j] = 1
                    if grid[i][j] == 0:
                        dp0[d][i][j] = 1
                else:
                    if grid[i][j] == 1:
                        dp1[d][i][j] = 1 + dp2[d][ni][nj]
                    if grid[i][j] == 2:
                        dp2[d][i][j] = 1 + dp0[d][ni][nj]
                    if grid[i][j] == 0:
                        dp0[d][i][j] = 1 + dp2[d][ni][nj]

        # Prefix length ending at cell (i,j) along direction d
        pref = [[[0] * m for _ in range(n)] for _ in range(4)]

        # Order for forward traversal (prev cell processed first)
        fwd_order = [
            [(i, j) for i in range(n) for j in range(m)],                 # d=0
            [(i, j) for i in range(n) for j in range(m-1, -1, -1)],        # d=1
            [(i, j) for i in range(n-1, -1, -1) for j in range(m)],      # d=2
            [(i, j) for i in range(n-1, -1, -1) for j in range(m-1, -1, -1)],  # d=3
        ]

        for d in range(4):
            for i, j in fwd_order[d]:
                pi, pj = i - dx[d], j - dy[d]
                prev_len = 0
                if 0 <= pi < n and 0 <= pj < m:
                    prev_len = pref[d][pi][pj]
                if grid[i][j] == 1:
                    pref[d][i][j] = 1
                elif grid[i][j] == 2 and prev_len > 0 and prev_len % 2 == 1:
                    pref[d][i][j] = prev_len + 1
                elif grid[i][j] == 0 and prev_len > 0 and prev_len % 2 == 0:
                    pref[d][i][j] = prev_len + 1
                else:
                    pref[d][i][j] = 0

        ans = 0
        # Straight segments
        for d in range(4):
            for i in range(n):
                for j in range(m):
                    if dp1[d][i][j] > ans:
                        ans = dp1[d][i][j]

        # Segments with one turn
        for i in range(n):
            for j in range(m):
                for d in range(4):
                    L = pref[d][i][j]
                    if L == 0:
                        continue
                    nd = (d + 1) % 4
                    ni, nj = i + dx[nd], j + dy[nd]
                    if 0 <= ni < n and 0 <= nj < m:
                        if L % 2 == 1:
                            suffix = dp2[nd][ni][nj]
                        else:
                            suffix = dp0[nd][ni][nj]
                        total = L + suffix
                        if total > ans:
                            ans = total
        return ans
