from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        if n == 2:
            res = INF
            for cL in range(3):
                for cR in range(3):
                    if cL != cR:
                        res = min(res, cost[0][cL] + cost[1][cR])
            return res

        m = n // 2  # number of pairs
        answer = INF

        # Precompute indices for pairs
        pair_indices = [(i, n - 1 - i) for i in range(m)]

        # Iterate over all initial states for the first pair
        for cL0 in range(3):
            for cR0 in range(3):
                if cL0 == cR0:
                    continue
                # DP arrays for current and previous pair
                dp_prev = [INF] * 9  # index = l*3 + r
                idx0 = cL0 * 3 + cR0
                dp_prev[idx0] = cost[0][cL0] + cost[n - 1][cR0]

                # Process remaining pairs
                for k in range(1, m):
                    i, j = pair_indices[k]
                    dp_curr = [INF] * 9
                    ci_cost = cost[i]
                    cj_cost = cost[j]
                    for prev_idx in range(9):
                        prev_cost = dp_prev[prev_idx]
                        if prev_cost == INF:
                            continue
                        prevL = prev_idx // 3
                        prevR = prev_idx % 3
                        for cL in range(3):
                            if cL == prevL:
                                continue
                            for cR in range(3):
                                if cR == prevR or cL == cR:
                                    continue
                                idx = cL * 3 + cR
                                new_cost = prev_cost + ci_cost[cL] + cj_cost[cR]
                                if new_cost < dp_curr[idx]:
                                    dp_curr[idx] = new_cost
                    dp_prev = dp_curr

                # After processing all pairs, enforce cycle closure
                for last_idx in range(9):
                    last_cost = dp_prev[last_idx]
                    if last_cost == INF:
                        continue
                    lastL = last_idx // 3
                    lastR = last_idx % 3
                    if lastL == cL0 or lastR == cR0:
                        continue
                    if last_cost < answer:
                        answer = last_cost

        return answer
