class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Precompute powers of 4 up to > 1e9
        powers = [1]
        while powers[-1] <= 10**9:
            powers.append(powers[-1] * 4)
        # function to compute sum of steps from 1 to x
        def sum_steps(x: int) -> int:
            if x <= 0:
                return 0
            total = 0
            for k, p in enumerate(powers):
                if p > x:
                    break
                next_p = powers[k+1] if k+1 < len(powers) else float('inf')
                upper = x if x < next_p - 1 else next_p - 1
                cnt = upper - p + 1
                total += (k + 1) * cnt
            return total
        result = 0
        for l, r in queries:
            total_steps = sum_steps(r) - sum_steps(l - 1)
            result += (total_steps + 1) // 2
        return result
