class Solution:
    def sortMatrix(self, grid):
        n = len(grid)
        from collections import defaultdict
        diag = defaultdict(list)
        for i in range(n):
            for j in range(n):
                d = i - j
                diag[d].append((i, j))
        for d, cells in diag.items():
            vals = [grid[i][j] for i, j in cells]
            if d >= 0:
                vals.sort(reverse=True)
            else:
                vals.sort()
            for (i, j), v in zip(cells, vals):
                grid[i][j] = v
        return grid
