class Solution:
    def maxFrequency(self, nums: list[int], k: int) -> int:
        n = len(nums)
        base = nums.count(k)
        best_add = 0
        # iterate over all possible target values a (1..50)
        for a in range(1, 51):
            if a == k:
                continue
            curr = 0
            best = 0
            for val in nums:
                if val == a:
                    curr += 1
                elif val == k:
                    curr -= 1
                # else curr unchanged
                if curr < 0:
                    curr = 0
                if curr > best:
                    best = curr
            if best > best_add:
                best_add = best
        return base + best_add
