from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        INF = 10**9
        max_val = max(max(groups, default=0), max(elements, default=0))
        min_index = [INF] * (max_val + 1)
        for idx, val in enumerate(elements):
            if idx < min_index[val]:
                min_index[val] = idx

        res = []
        for g in groups:
            best = INF
            limit = int(g**0.5)
            for d in range(1, limit + 1):
                if g % d == 0:
                    idx1 = min_index[d]
                    if idx1 < best:
                        best = idx1
                    d2 = g // d
                    if d2 != d:
                        idx2 = min_index[d2]
                        if idx2 < best:
                            best = idx2
            res.append(-1 if best == INF else best)
        return res
