class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        # naive O(n^2) solution
        for l in range(n):
            cur_max = nums[l]
            cost = 0
            for r in range(l, n):
                if r == l:
                    cur_max = nums[r]
                else:
                    cur_max = max(cur_max, nums[r])
                    cost += cur_max - nums[r]
                if cost <= k:
                    total += 1
        return total
