class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        word = ['?'] * L
        # Precompute coverage lists
        coverage = [[] for _ in range(L)]
        for i in range(n):
            for pos in range(i, i + m):
                coverage[pos].append(i)
        # Place T constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    req = str2[j]
                    if word[pos] == '?' or word[pos] == req:
                        word[pos] = req
                    else:
                        return ""
        # Count matches for each window
        cnt = [0] * n
        for i in range(n):
            c = 0
            for j in range(m):
                pos = i + j
                if word[pos] == str2[j]:
                    c += 1
            cnt[i] = c
        # Check F windows initially not fully matched
        for i in range(n):
            if str1[i] == 'F' and cnt[i] == m:
                return ""
        # Greedy assignment for free positions
        for pos in range(L):
            if word[pos] != '?':
                continue
            for ci in range(26):
                c = chr(ord('a') + ci)
                ok = True
                for i in coverage[pos]:
                    if str1[i] == 'F':
                        off = pos - i
                        new_match = (c == str2[off])
                        new_cnt = cnt[i] + (1 if new_match else 0)
                        if new_cnt == m:
                            ok = False
                            break
                if ok:
                    word[pos] = c
                    for i in coverage[pos]:
                        if str1[i] == 'F':
                            off = pos - i
                            if c == str2[off]:
                                cnt[i] += 1
                    break
            else:
                return ""
        return ''.join(word)
