class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        last = [-1] * 26
        for i, ch in enumerate(s):
            last[ord(ch) - 97] = i
        count = 0
        cur_max = -1
        for i, ch in enumerate(s):
            cur_max = max(cur_max, last[ord(ch) - 97])
            if i == cur_max:
                if i == n - 1 and count == 0:
                    # This would be the whole string; cannot count
                    count = 0
                    break
                count += 1
        return count >= k
