            if first[idx] == -1:
                first[idx] = i
            last[idx] = i

        intervals = []
        for l in range(n):
            idx = ord(s[l]) - 97
            if first[idx] != l:
                continue  # only start at first occurrence
            max_last = last[idx]
            r = l
            valid = True
            while r < max_last:
                r += 1
                idx2 = ord(s[r]) - 97
                if first[idx2] < l:
                    valid = False
                    break
                if last[idx2] > max_last:
                    max_last = last[idx2]
            if not valid:
                continue
            if l == 0 and max_last == n - 1:
                continue  # cannot be entire string
            intervals.append((l, max_last))

        # Greedy interval scheduling
        intervals.sort(key=lambda x: x[1])
        cnt = 0
        last_end = -1
        for start, end in intervals:
            if start > last_end:
                cnt += 1
                last_end = end
                if cnt >= k:
                    return True
        return False
