class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp set of tuples (sum, product, parity)
        dp = set()
        for x in nums:
            newdp = set(dp)  # skip x
            # start new subsequence with x
            if x <= limit:
                newdp.add((x, x, 1))  # parity flips to 1
            for s, p, parity in dp:
                newsum = s + (x if parity == 0 else -x)
                newprod = p * x
                if newprod <= limit:
                    newparity = 1 - parity
                    newdp.add((newsum, newprod, newparity))
            dp = newdp
        best = -1
        for s, p, _ in dp:
            if s == k and p <= limit:
                if p > best:
                    best = p
        return best
