from typing import List, Tuple, Dict

class Solution:
    def minCost(self, nums: List[int]) -> int:
        # DP state: buffer tuple -> minimal cost so far
        dp: Dict[Tuple[int, ...], int] = {(): 0}

        for x in nums:
            new_dp: Dict[Tuple[int, ...], int] = {}
            for buf_tuple, cost_so_far in dp.items():
                buffer = list(buf_tuple)
                b = buffer + [x]
                L = len(b)
                results = []

                if L <= 3:
                    # keep as is (no pop)
                    results.append((tuple(b), cost_so_far))
                    # pop one pair if possible
                    if L >= 2:
                        for i in range(L):
                            for j in range(i + 1, L):
                                rem = [b[k] for k in range(L) if k != i and k != j]
                                new_cost = cost_so_far + max(b[i], b[j])
                                results.append((tuple(rem), new_cost))
                else:  # L == 4
                    # pop one pair
                    for i in range(L):
                        for j in range(i + 1, L):
                            rem = [b[k] for k in range(L) if k != i and k != j]
                            new_cost = cost_so_far + max(b[i], b[j])
                            results.append((tuple(rem), new_cost))
                    # pop two pairs (remove all 4)
                    # enumerate all pairings
                    pairings = [((0, 1), (2, 3)), ((0, 2), (1, 3)), ((0, 3), (1, 2))]
                    for p1, p2 in pairings:
                        max1 = max(b[p1[0]], b[p1[1]])
                        max2 = max(b[p2[0]], b[p2[1]])
                        new_cost = cost_so_far + max1 + max2
                        results.append(((), new_cost))

                for new_buf, new_cost in results:
                    if new_buf in new_dp:
                        if new_cost < new_dp[new_buf]:
                            new_dp[new_buf] = new_cost
                    else:
                        new_dp[new_buf] = new_cost
            dp = new_dp

        # function to compute minimal cost to empty a buffer of up to 3 elements
        def cost_to_empty(buf: Tuple[int, ...]) -> int:
            l = len(buf)
            if l == 0:
                return 0
            if l == 1:
                return buf[0]
            if l == 2:
                return max(buf[0], buf[1])
            # l == 3
            best = float('inf')
            for i in range(3):
                for j in range(i + 1, 3):
                    k = 3 - i - j  # remaining index
                    cost = max(buf[i], buf[j]) + buf[k]
                    if cost < best:
                        best = cost
            return best

        ans = float('inf')
        for buf, cost_so_far in dp.items():
            total = cost_so_far + cost_to_empty(buf)
            if total < ans:
                ans = total
        return ans
