class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        pts = [(x, y) for x, y in points]

        def feasible(d: int) -> bool:
            if d <= 0:
                return True
            remaining = list(range(n))

            def backtrack(rem: List[int], cnt: int) -> bool:
                # prune
                if cnt >= k:
                    return True
                if len(rem) + cnt < k:
                    return False
                # choose next vertex
                v = rem[0]
                pv = pts[v]
                # include branch
                new_rem = []
                pvx, pvy = pv
                for u in rem[1:]:
                    ux, uy = pts[u]
                    if abs(pvx - ux) + abs(pvy - uy) >= d:
                        new_rem.append(u)
                if backtrack(new_rem, cnt + 1):
                    return True
                # exclude branch
                return backtrack(rem[1:], cnt)

            return backtrack(remaining, 0)

        lo, hi = 0, 2 * side + 1
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid
        return lo
