            return abs(points[a][0] - points[b][0]) + abs(points[a][1] - points[b][1])

        # Binary search on answer
        lo, hi = 0, 2 * side
        best = 0
        # To avoid deep recursion, we limit recursion depth to k (max 25)
        sys.setrecursionlimit(10000)

        # Main feasibility check using DFS with pruning
        def can(d: int) -> bool:
            selected = []

            # Memoization dictionary for pruning: key = (idx, len(selected))
            memo = {}

            def dfs(idx: int, cnt: int) -> bool:
                # If we already have k points, success
                if cnt == k:
                    return True
                # If not enough points left, fail
                if idx >= n or cnt + (n - idx) < k:
                    return False
                key = (idx, cnt)
                if key in memo:
                    return False
                for i in range(idx, n):
                    # Quick bound
                    if cnt + (n - i) < k:
                        break
                    ok = True
                    pi = points[i]
                    # Check against all selected points
                    for j in selected:
                        if abs(pi[0] - points[j][0]) + abs(pi[1] - points[j][1]) < d:
                            ok = False
                            break
                    if not ok:
                        continue
                    selected.append(i)
                    if dfs(i + 1, cnt + 1):
                        return True
                    selected.pop()
                memo[key] = False
                return False

            return dfs(0, 0)

        # Binary search for maximum d
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                best = mid
                lo = mid + 1
