from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Precompute Manhattan distances for all pairs
        # We'll build conflict lists only for pairs that are too close (< d)
        def build_conflicts(d: int):
            conf = [[] for _ in range(n)]
            for i in range(n):
                xi, yi = points[i]
                for j in range(i + 1, n):
                    xj, yj = points[j]
                    if abs(xi - xj) + abs(yi - yj) < d:
                        conf[i].append(j)
            return conf

        # Backtracking search to find independent set of size k
        def can(d: int) -> bool:
            conf = build_conflicts(d)
            banned = [False] * n

            def dfs(idx: int, selected: int) -> bool:
                if selected == k:
                    return True
                # Quick pruning: not enough points left
                remaining = 0
                for i in range(idx, n):
                    if not banned[i]:
                        remaining += 1
                if remaining + selected < k:
                    return False
                for i in range(idx, n):
                    if banned[i]:
                        continue
                    # choose point i
                    added = []
                    for j in conf[i]:
                        if not banned[j]:
                            banned[j] = True
                            added.append(j)
                    banned[i] = True
                    if dfs(i + 1, selected + 1):
                        return True
                    banned[i] = False
                    for j in added:
                        banned[j] = False
                return False

            return dfs(0, 0)

        lo, hi = 1, 2 * side
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans
