from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        # dp[odd][even][p] where p=0 even, p=1 odd
        dp = [[[0, 0] for _ in range(even_count + 1)] for _ in range(odd_count + 1)]
        dp[0][0][0] = dp[0][0][1] = 1

        for total in range(1, odd_count + even_count + 1):
            for odd in range(0, odd_count + 1):
                even = total - odd
                if even < 0 or even > even_count:
                    continue
                # parity 0 (even)
                if even > 0:
                    dp[odd][even][0] = even * dp[odd][even - 1][1]
                else:
                    dp[odd][even][0] = 0
                # parity 1 (odd)
                if odd > 0:
                    dp[odd][even][1] = odd * dp[odd - 1][even][0]
                else:
                    dp[odd][even][1] = 0

        # total number of alternating permutations
        total_perms = 0
        if odd_count > 0:
            total_perms += odd_count * dp[odd_count - 1][even_count][0]
        if even_count > 0:
            total_perms += even_count * dp[odd_count][even_count - 1][1]
        if k > total_perms:
            return []

        used = [False] * (n + 1)
        res: List[int] = []
        odd_rem = odd_count
        even_rem = even_count

        for _ in range(n):
            chosen = False
            for cand in range(1, n + 1):
                if used[cand]:
                    continue
                p = cand & 1  # 0 even, 1 odd
                if p == 1 and odd_rem == 0:
                    continue
                if p == 0 and even_rem == 0:
                    continue
                new_odd = odd_rem - (p == 1)
                new_even = even_rem - (p == 0)
                cnt = dp[new_odd][new_even][1 - p]
                if k > cnt:
                    k -= cnt
                    continue
                # select this candidate
                res.append(cand)
                used[cand] = True
                odd_rem = new_odd
                even_rem = new_even
                chosen = True
                break
            if not chosen:
                return []
        return res
