from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        # Trie node data
        children = []
        count = []
        depth = []
        indices = []
        # initialize root
        children.append({})
        count.append(0)
        depth.append(0)
        indices.append([])
        # build trie
        for idx, w in enumerate(words):
            node = 0
            for ch in w:
                if ch not in children[node]:
                    children[node][ch] = len(children)
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                    indices.append([])
                node = children[node][ch]
                count[node] += 1
                indices[node].append(idx)
        # compute max depth > k
        max_depth_gt_k = 0
        depths_eq_k_set = set()
        for i in range(1, len(children)):
            if count[i] > k:
                if depth[i] > max_depth_gt_k:
                    max_depth_gt_k = depth[i]
            if count[i] == k:
                depths_eq_k_set.add(depth[i])
        if depths_eq_k_set:
            depths_eq_k = sorted(depths_eq_k_set, reverse=True)
            d1 = depths_eq_k[0]
            d2 = depths_eq_k[1] if len(depths_eq_k) > 1 else None
        else:
            d1 = None
            d2 = None
        # build sets of word indices for nodes at depth d1 and d2
        S1 = set()
        S2 = set()
        if d1 is not None:
            for i in range(1, len(children)):
                if count[i] == k and depth[i] == d1:
                    S1.update(indices[i])
        if d2 is not None:
            for i in range(1, len(children)):
                if count[i] == k and depth[i] == d2:
                    S2.update(indices[i])
        res = [0] * n
        if n - 1 < k:
            return res
        for i in range(n):
            ans = max_depth_gt_k
            if d1 is not None:
                if i not in S1:
                    ans = max(ans, d1)
                elif d2 is not None:
                    ans = max(ans, d2)
            res[i] = ans
        return res
