from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute counts of odd/even numbers
        odds = (n + 1) // 2
        evens = n // 2

        # DP tables
        dp_none = [[0] * (evens + 1) for _ in range(odds + 1)]
        dp_odd = [[0] * (evens + 1) for _ in range(odds + 1)]
        dp_even = [[0] * (evens + 1) for _ in range(odds + 1)]
        dp_none[0][0] = dp_odd[0][0] = dp_even[0][0] = 1

        for o in range(odds + 1):
            for e in range(evens + 1):
                if o == 0 and e == 0:
                    continue
                dp_odd[o][e] = e * dp_even[o][e-1] if e > 0 else 0
                dp_even[o][e] = o * dp_odd[o-1][e] if o > 0 else 0
                val = 0
                if o > 0:
                    val += o * dp_odd[o-1][e]
                if e > 0:
                    val += e * dp_even[o][e-1]
                dp_none[o][e] = val

        total = dp_none[odds][evens]
        if k > total:
            return []

        # Remaining numbers
        odd_list = [i for i in range(1, n + 1) if i % 2 == 1]
        even_list = [i for i in range(1, n + 1) if i % 2 == 0]
        result = []
        last_parity = None  # None means no restriction

        for pos in range(n):
            # Determine candidate list
            if last_parity is None:
                candidates = []
                # Merge two lists preserving order
                oi = ei = 0
                while oi < len(odd_list) and ei < len(even_list):
                    if odd_list[oi] < even_list[ei]:
                        candidates.append(odd_list[oi]); oi += 1
                    else:
                        candidates.append(even_list[ei]); ei += 1
                while oi < len(odd_list):
                    candidates.append(odd_list[oi]); oi += 1
                while ei < len(even_list):
                    candidates.append(even_list[ei]); ei += 1
            else:
                if last_parity == 0:  # last odd, need even
                    candidates = even_list[:]
                else:  # last even, need odd
                    candidates = odd_list[:]

            chosen = None
            for num in candidates:
                # Compute remaining counts after picking num
                if num % 2 == 1:
                    rem_o = len(odd_list) - 1
                    rem_e = len(even_list)
                else:
                    rem_o = len(odd_list)
                    rem_e = len(even_list) - 1

                # Count suffix permutations
                if num % 2 == 1:
                    suffix = dp_odd[rem_o][rem_e]
                else:
                    suffix = dp_even[rem_o][rem_e]

                if suffix >= k:
                    chosen = num
                    result.append(num)
                    # Remove chosen from list
                    if num % 2 == 1:
                        odd_list.remove(num)
                        last_parity = 0
                    else:
                        even_list.remove(num)
                        last_parity = 1
                    break
                else:
                    k -= suffix

            if chosen is None:
                # Should not happen if total >= original k
                return []

        return result
