    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2
        # dp[odd][even][p] : number of alternating perms of remaining numbers
        # with odd count 'odd', even count 'even', starting with parity p (0 even, 1 odd)
        dp = [[[0, 0] for _ in range(even_count + 1)] for _ in range(odd_count + 1)]
        dp[0][0][0] = dp[0][0][1] = 1
        for total in range(1, odd_count + even_count + 1):
            for odd in range(0, odd_count + 1):
                even = total - odd
                if even < 0 or even > even_count:
                    continue
                if even > 0:
                    dp[odd][even][0] = even * dp[odd][even - 1][1]
                else:
                    dp[odd][even][0] = 0
                if odd > 0:
                    dp[odd][even][1] = odd * dp[odd - 1][even][0]
                else:
                    dp[odd][even][1] = 0
        total_perms = dp[odd_count][even_count][0] + dp[odd_count][even_count][1]
        if k > total_perms:
            return []
        used = [False] * (n + 1)
        result: List[int] = []
        odd_rem, even_rem = odd_count, even_count
        prev_p = None  # parity of previous element
        for _ in range(n):
            found = False
            for cand in range(1, n + 1):
                if used[cand]:
                    continue
                p = cand & 1  # 0 even, 1 odd
                if p == 1 and odd_rem == 0:
                    continue
                if p == 0 and even_rem == 0:
                    continue
                if prev_p is not None and p == prev_p:
                    continue
                new_odd = odd_rem - (p == 1)
                new_even = even_rem - (p == 0)
                cnt = dp[new_odd][new_even][1 - p]
                if k > cnt:
                    k -= cnt
                    continue
                # choose this candidate
                result.append(cand)
                used[cand] = True
                odd_rem, even_rem = new_odd, new_even
                prev_p = p
                found = True
                break
            if not found:
                return []
        return result
