from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1
        seg = [-10**18] * (2 * size)
        # build
        for i in range(n):
            seg[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos, val):
            idx = size + pos
            seg[idx] = val
            idx //= 2
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        def find_first(v, node, l, r):
            if seg[node] < v:
                return -1
            if l == r:
                return l
            mid = (l + r) >> 1
            if seg[2 * node] >= v:
                return find_first(v, 2 * node, l, mid)
            else:
                return find_first(v, 2 * node + 1, mid + 1, r)

        unplaced = 0
        for f in fruits:
            idx = find_first(f, 1, 0, size - 1)
            if idx == -1 or idx >= n:
                unplaced += 1
            else:
                update(idx, -10**18)
        return unplaced
