class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        maxSum = max(nums) if nums else 0
        limit = (1 << (maxSum + 1)) - 1
        masks = [1] * n  # bit 0 set initially
        # check before any query
        if all((masks[i] >> nums[i]) & 1 for i in range(n)):
            return 0
        for k, (l, r, val) in enumerate(queries, 1):
            shift = val
            for i in range(l, r + 1):
                masks[i] |= (masks[i] << shift) & limit
            if all((masks[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1
