class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        import sys
        sys.setrecursionlimit(10000)
        # Precompute dp_len[s][L] and count_nozero_len[L]
        max_len = 9
        max_sum = 9 * max_len  # 81
        dp_len = [[0] * (max_len + 1) for _ in range(max_sum + 1)]  # dp_len[s][L]
        for s in range(1, max_sum + 1):
            for L in range(1, max_len + 1):
                # DP over positions
                dp = [[0] * s for _ in range(L + 1)]  # dp[pos][sum][mod]
                init_mod = 0 if s == 1 else 1 % s
                dp[0][0][init_mod] = 1
                for pos in range(L):
                    for sm in range(s + 1):
                        for mod in range(s):
                            val = dp[pos][sm][mod]
                            if val == 0:
                                continue
                            for d in range(1, 10):
                                nsm = sm + d
                                if nsm > s:
                                    continue
                                nmod = (mod * d) % s if s > 1 else 0
                                dp[pos + 1][nsm][nmod] += val
                dp_len[s][L] = dp[L][s][0]
        # count_nozero_len[L] = 9^L
        pow9 = [1] * (max_len + 1)
        for i in range(1, max_len + 1):
            pow9[i] = pow9[i - 1] * 9
        count_nozero_len = pow9

        def count_nozero_upto(N: int) -> int:
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            nlen = len(digits)
            total = 0
            for L in range(1, nlen):
                total += count_nozero_len[L]
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool) -> int:
                if pos == nlen:
                    return 1
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(1, limit + 1):
                    if d == 0:
                        continue
                    ntight = tight and (d == limit)
                    res += dfs(pos + 1, ntight)
                return res
            total += dfs(0, True)
            return total

        def count_beautiful_upto(N: int) -> int:
            if N <= 0:
                return 0
            # numbers with at least one zero digit
            count_nozero = count_nozero_upto(N)
            count_zero = N - count_nozero
            total = count_zero
            digits = list(map(int, str(N)))
            nlen = len(digits)
            from functools import lru_cache
            for s in range(1, max_sum + 1):
                # count numbers with no zero digits, sum==s, product divisible by s
                # add lengths shorter than nlen
                for L in range(1, nlen):
                    total += dp_len[s][L]
                # count numbers with length nlen and <=N
                init_mod = 0 if s == 1 else 1 % s
                @lru_cache(maxsize=None)
                def dfs(pos: int, tight: bool, sm: int, mod: int) -> int:
                    if sm > s:
                        return 0
                    if pos == nlen:
                        return 1 if sm == s and mod == 0 else 0
                    limit = digits[pos] if tight else 9
                    res = 0
                    for d in range(1, limit + 1):
                        if d == 0:
                            continue
                        nsm = sm + d
                        if nsm > s:
                            continue
                        nmod = (mod * d) % s if s > 1 else 0
                        ntight = tight and (d == limit)
                        res += dfs(pos + 1, ntight, nsm, nmod)
                    return res
                total += dfs(0, True, 0, init_mod)
            return total

        return count_beautiful_upto(r) - count_beautiful_upto(l - 1)
