class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0
        runs = []
        total_ones = 0
        prev = s[0]
        cnt = 1
        if prev == '1':
            total_ones = 1
        for ch in s[1:]:
            if ch == prev:
                cnt += 1
            else:
                runs.append((prev, cnt))
                if prev == '1':
                    total_ones += cnt
                prev = ch
                cnt = 1
        runs.append((prev, cnt))
        if prev == '1':
            total_ones += cnt

        max_inc = 0
        m = len(runs)
        for i in range(1, m - 1):
            typ, length = runs[i]
            if typ == '1':
                left_len = runs[i - 1][1]
                right_len = runs[i + 1][1]
                inc = left_len + right_len
                if inc > max_inc:
                    max_inc = inc

        return min(total_ones + max_inc, n)
