class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_with_zero(N: int) -> int:
            digits = list(map(int, str(N)))

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, hasZero: bool, started: bool) -> int:
                if pos == len(digits):
                    return 1 if started and hasZero else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    ntight = tight and d == limit
                    nstarted = started or d != 0
                    nhasZero = hasZero or (nstarted and d == 0)
                    res += dfs(pos + 1, ntight, nhasZero, nstarted)
                return res

            return dfs(0, True, False, False)

        def count_no_zero_and_divisible(N: int) -> int:
            digits = list(map(int, str(N)))
            total = 0

            for s in range(1, 82):  # possible sums 1..81
                @lru_cache(maxsize=None)
                def dfs(pos: int, sum_so_far: int, prod_mod: int, started: bool, tight: bool) -> int:
                    if pos == len(digits):
                        return 1 if started and sum_so_far == s and prod_mod == 0 else 0
                    limit = digits[pos] if tight else 9
                    res = 0
                    for d in range(0, limit + 1):
                        ntight = tight and d == limit
                        nstarted = started or d != 0
                        if not nstarted:
                            # leading zeros, do not add to sum or product
                            res += dfs(pos + 1, sum_so_far, prod_mod, False, ntight)
                        else:
                            if d == 0:
                                # zero digit not allowed in this branch
                                continue
                            new_sum = sum_so_far + d
                            if new_sum > s:
                                continue
                            new_prod = (prod_mod * d) % s if s != 0 else 0
                            res += dfs(pos + 1, new_sum, new_prod, True, ntight)
                    return res

                total += dfs(0, 0, 1 % s, False, True)
            return total

        def solve_for(N: int) -> int:
            if N <= 0:
                return 0
            return count_with_zero(N) + count_no_zero_and_divisible(N)

        return solve_for(r) - solve_for(l - 1)
