class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        import sys
        sys.setrecursionlimit(10000)
        from functools import lru_cache

        def count_nonzero_upto(N: int) -> int:
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            nlen = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool) -> int:
                if pos == nlen:
                    return 1 if started else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    ntight = tight and (d == limit)
                    if started:
                        if d == 0:
                            continue  # zero digit not allowed after start
                        res += dfs(pos + 1, ntight, True)
                    else:
                        if d == 0:
                            res += dfs(pos + 1, ntight, False)
                        else:
                            res += dfs(pos + 1, ntight, True)
                return res

            return dfs(0, True, False)

        def count_with_sum_and_product_mod(N: int, s: int) -> int:
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            nlen = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool, sum_so_far: int, prod_mod: int) -> int:
                if pos == nlen:
                    return 1 if started and sum_so_far == s and prod_mod == 0 else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    ntight = tight and (d == limit)
                    if started:
                        if d == 0:
                            continue  # zero digit not allowed after start
                        new_sum = sum_so_far + d
                        if new_sum > s:
                            continue
                        new_prod_mod = (prod_mod * d) % s
                        res += dfs(pos + 1, ntight, True, new_sum, new_prod_mod)
                    else:
                        if d == 0:
                            res += dfs(pos + 1, ntight, False, sum_so_far, prod_mod)
                        else:
                            new_sum = sum_so_far + d
                            if new_sum > s:
                                continue
                            new_prod_mod = d % s
                            res += dfs(pos + 1, ntight, True, new_sum, new_prod_mod)
                return res

            return dfs(0, True, False, 0, 0)

        def count_beautiful_upto(N: int) -> int:
            if N <= 0:
                return 0
            nonzero_count = count_nonzero_upto(N)
            zero_count = N - nonzero_count
            total = zero_count
            digits_len = len(str(N))
            max_sum = 9 * digits_len
            for s in range(1, max_sum + 1):
                total += count_with_sum_and_product_mod(N, s)
            return total

        return count_beautiful_upto(r) - count_beautiful_upto(l - 1)
