import sys
import threading

def solve() -> None:
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))
    contests = [(int(next(it)), int(next(it))) for _ in range(N)]
    Q = int(next(it))
    queries = [(int(next(it)), idx) for idx in range(Q)]
    # sort queries by initial rating
    queries.sort(key=lambda x: x[0])
    cur_base = [x for x, _ in queries]  # base ratings sorted

    size = Q
    if size == 0:
        return

    minv = [0] * (4 * size)
    maxv = [0] * (4 * size)
    lazy = [0] * (4 * size)

    def build(node, l, r):
        if l == r:
            minv[node] = maxv[node] = cur_base[l]
        else:
            mid = (l + r) // 2
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            minv[node] = min(minv[node * 2], minv[node * 2 + 1])
            maxv[node] = max(maxv[node * 2], maxv[node * 2 + 1])

    def push(node):
        if lazy[node]:
            v = lazy[node]
            for child in (node * 2, node * 2 + 1):
                lazy[child] += v
                minv[child] += v
                maxv[child] += v
            lazy[node] = 0

    def range_add(node, l, r, ql, qr, val):
        if qr < l or r < ql:
            return
        if ql <= l and r <= qr:
            minv[node] += val
            maxv[node] += val
            lazy[node] += val
            return
        push(node)
        mid = (l + r) // 2
        range_add(node * 2, l, mid, ql, qr, val)
        range_add(node * 2 + 1, mid + 1, r, ql, qr, val)
        minv[node] = min(minv[node * 2], minv[node * 2 + 1])
        maxv[node] = max(maxv[node * 2], maxv[node * 2 + 1])

    def find_left(node, l, r, val):
        if maxv[node] < val:
            return -1
        if l == r:
            return l
        push(node)
        mid = (l + r) // 2
        res = find_left(node * 2, l, mid, val)
        if res != -1:
            return res
        return find_left(node * 2 + 1, mid + 1, r, val)

    def find_right(node, l, r, val):
        if minv[node] > val:
            return -1
        if l == r:
            return l
        push(node)
        mid = (l + r) // 2
        res = find_right(node * 2 + 1, mid + 1, r, val)
        if res != -1:
            return res
        return find_right(node * 2, l, mid, val)

    def query_point(node, l, r, idx):
        if l == r:
            return minv[node]
        push(node)
        mid = (l + r) // 2
        if idx <= mid:
            return query_point(node * 2, l, mid, idx)
        else:
            return query_point(node * 2 + 1, mid + 1, r, idx)

    build(1, 0, size - 1)

    for L, R in contests:
        l_idx = find_left(1, 0, size - 1, L)
        if l_idx == -1:
            continue
        r_idx = find_right(1, 0, size - 1, R)
        if r_idx == -1 or l_idx > r_idx:
            continue
        range_add(1, 0, size - 1, l_idx, r_idx, 1)

    ans = [0] * Q
    for idx_sorted, (_, orig) in enumerate(queries):
        final_val = query_point(1, 0, size - 1, idx_sorted)
        ans[orig] = final_val

    out = '\n'.join(map(str, ans))
    sys.stdout.write(out)

def main():
    solve()

threading.Thread(target=main).start()
