import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    max_edges = N * (N - 1) // 2

    # binomial coefficients modulo P
    C = [[0] * (max_edges + 1) for _ in range(max_edges + 1)]
    for n in range(max_edges + 1):
        C[n][0] = 1
        for k in range(1, n + 1):
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % P

    # internal edges polynomial for each layer size s
    internal_poly = [defaultdict(int) for _ in range(N + 1)]  # index by s
    for s in range(1, N + 1):
        m = s * (s - 1) // 2
        for e in range(m + 1):
            internal_poly[s][e] = C[m][e]

    # precompute bipartite polynomials: bip[a][b][e_total]
    bip_poly = [[defaultdict(int) for _ in range(N + 1)] for _ in range(N + 1)]
    for a in range(1, N + 1):
        # base polynomial f(x) = (1+x)^a - 1
        f = defaultdict(int)
        for k in range(1, a + 1):
            f[k] = C[a][k]
        # compute f^b
        for b in range(1, N + 1):
            # convolution of f b times
            poly = defaultdict(int)
            poly[0] = 1  # start with polynomial 1
            for _ in range(b):
                new_poly = defaultdict(int)
                for e1, v1 in poly.items():
                    for e2, v2 in f.items():
                        new_poly[e1 + e2] = (new_poly[e1 + e2] + v1 * v2) % P
                poly = new_poly
            bip_poly[a][b] = poly

    # combine bipartite and internal polynomials
    comb_poly = [[defaultdict(int) for _ in range(N + 1)] for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # convolve bip_poly[a][b] with internal_poly[b]
            res = defaultdict(int)
            bip = bip_poly[a][b]
            intr = internal_poly[b]
            for eb, vb in bip.items():
                for ei, vi in intr.items():
                    e_total = eb + ei
                    if e_total <= max_edges:
                        res[e_total] = (res[e_total] + vb * vi) % P
            comb_poly[a][b] = res

    # DP: states_per_v[v] is dict with key=(even,edges,prev_size,parity)
    states_per_v = [defaultdict(int) for _ in range(N + 1)]
    # initial state: level0 size 1, even count 1, edges 0, prev_size=1, parity=0 (level0)
    states_per_v[1][(1, 0, 1, 0)] = 1

    for v in range(1, N):
        cur_states = states_per_v[v]
        if not cur_states:
            continue
        for (even, edges, prev_size, parity), cnt in cur_states.items():
            max_s = N - v
            for s in range(1, max_s + 1):
                new_v = v + s
                new_parity = 1 - parity
                new_even = even + (s if parity == 1 else 0)
                if new_even > N:
                    continue
                poly = comb_poly[prev_size][s]
                for e_total, cnt_layer in poly.items():
                    new_edges = edges + e_total
                    if new_edges > max_edges:
                        continue
                    key = (new_even, new_edges, s, new_parity)
                    states_per_v[new_v][key] = (states_per_v[new_v][key] + cnt * cnt_layer) % P

    # gather answers
    out = []
    target_even = N // 2
    for M in range(N - 1, max_edges + 1):
        ans = 0
        for (even, edges, prev_size, parity), cnt in states_per_v[N].items():
            if even == target_even and edges == M:
                ans = (ans + cnt) % P
        out.append(str(ans))
    sys.stdout.write(' '.join(out))

if __name__ == "__main__":
    solve()
