    N, X = map(int, input().split())
    items_by_type = {1: [], 2: [], 3: []}
    for _ in range(N):
        v, a, c = map(int, input().split())
        items_by_type[v].append((a, c))

    INF_NEG = -10**18

    def knap(items):
        dp = [INF_NEG] * (X + 1)
        dp[0] = 0
        for a, c in items:
            if c > X:  # skip if cannot fit at all
                continue
            for cap in range(X, c - 1, -1):
                prev = dp[cap - c]
                if prev != INF_NEG:
                    val = prev + a
                    if val > dp[cap]:
                        dp[cap] = val
        return dp

    dp1 = knap(items_by_type[1])
    dp2 = knap(items_by_type[2])
    dp3 = knap(items_by_type[3])

    # Prefix maximum for dp3
    pref3 = [INF_NEG] * (X + 1)
    mx = INF_NEG
    for i in range(X + 1):
        if dp3[i] > mx:
            mx = dp3[i]
        pref3[i] = mx

    ans = 0
    for c1 in range(X + 1):
        v1 = dp1[c1]
        if v1 < 0:
            continue
        rem1 = X - c1
        for c2 in range(rem1 + 1):
            v2 = dp2[c2]
            if v2 < 0:
                continue
            rem2 = rem1 - c2
            v3 = pref3[rem2]
            if v3 < 0:
                continue
            mn = v1
            if v2 < mn:
                mn = v2
            if v3 < mn:
                mn = v3
            if mn > ans:
                ans = mn

    print(ans)

