import sys
import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0]); P = int(data[1])
    a = N // 2
    max_edges = a * a

    # factorials up to a*a for combinations
    fact = [1] * (max_edges + 1)
    for i in range(1, max_edges + 1):
        fact[i] = fact[i-1] * i % P
    invfact = [1] * (max_edges + 1)
    invfact[max_edges] = pow(fact[max_edges], P-2, P)
    for i in range(max_edges, 0, -1):
        invfact[i-1] = invfact[i] * i % P

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % P * invfact[n-k] % P

    # precompute g[i][j][m] = C(i*j, m)
    g = [[[0]*(i*j+1) for j in range(a+1)] for i in range(a+1)]
    for i in range(a+1):
        for j in range(a+1):
            ij = i*j
            for m in range(ij+1):
                g[i][j][m] = comb(ij, m)

    # f[i][j] as list of length i*j+1
    f = [[[0]*(i*j+1) for j in range(a+1)] for i in range(a+1)]
    # base
    f[1][0][0] = 1
    f[0][1][0] = 1  # though not needed
    # compute increasing total vertices
    for total in range(1, 2*a+1):
        for i in range(1, a+1):
            j = total - i
            if j < 0 or j > a:
                continue
            if i==1 and j==0:
                continue  # already set
            if i==0 and j==1:
                continue
            ij = i*j
            f[i][j] = g[i][j][:]  # copy list
            for i1 in range(1, i+1):
                for j1 in range(0, j+1):
                    if i1==i and j1==j:
                        continue
                    ij1 = i1*j1
                    remi = i - i1
                    remj = j - j1
                    remij = remi*remj
                    if remij < 0:
                        continue
                    coef1 = comb(i-1, i1-1)  # choose other A vertices for component containing vertex1
                    coef2 = comb(j, j1)      # choose B vertices for component
                    for m1 in range(ij1+1):
                        val1 = f[i1][j1][m1]
                        if val1==0:
                            continue
                        for m2 in range(remij+1):
                            val2 = g[remi][remj][m2]
                            if val2==0:
                                continue
                            m = m1 + m2
                            if m > ij:
                                continue
                            f[i][j][m] = (f[i][j][m] - val1 * val2 % P * coef1 % P * coef2 % P) % P

    # choose which vertices are in part A
    choose_A = comb(N-1, a-1)

    res = []
    for M in range(N-1, max_edges+1):
        if M > max_edges:
            res.append(0)
        else:
            res.append(choose_A * f[a][a][M] % P)
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()
