import sys
import threading
def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    N, P = map(int, sys.stdin.readline().split())
    max_edges = N * (N - 1) // 2

    # factorials up to max_edges
    fact = [1] * (max_edges + 1)
    for i in range(1, max_edges + 1):
        fact[i] = fact[i - 1] * i % P
    invfact = [1] * (max_edges + 1)
    invfact[max_edges] = pow(fact[max_edges], P - 2, P)
    for i in range(max_edges, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % P * invfact[n - k] % P

    # Precompute inter-layer counts: dict (p,q) -> dict t->ways
    inter_counts = {}
    for p in range(1, N):  # previous layer size
        for q in range(1, N):  # current layer size
            key = (p, q)
            max_t = p * q
            ways_t = {}
            # Use inclusion-exclusion: sum_{j=0}^{q} (-1)^j * C(q,j) * C(p*(q-j), t)
            for t in range(0, max_t + 1):
                total = 0
                for j in range(0, q + 1):
                    sign = -1 if j & 1 else 1
                    rem_q = q - j
                    max_edges_rem = p * rem_q
                    if t > max_edges_rem:
                        continue
                    term = C(q, j) * C(max_edges_rem, t) % P
                    if sign == 1:
                        total += term
                    else:
                        total -= term
                total %= P
                if total:
                    ways_t[t] = total
            inter_counts[key] = ways_t

    # Precompute intra-layer counts: dict q -> dict s->ways
    intra_counts = {}
    for q in range(1, N):
        total_edges = q * (q - 1) // 2
        ways_s = {}
        for s in range(0, total_edges + 1):
            ways_s[s] = C(total_edges, s)
        intra_counts[q] = ways_s

    # Precompute combined edge counts for (prev, cur)
    combined_counts = {}
    for key, inter_dict in inter_counts.items():
        p, q = key
        intra_dict = intra_counts[q]
        comb = {}
        for t, w_t in inter_dict.items():
            for s, w_s in intra_dict.items():
                e = t + s
                if e > max_edges:
                    continue
                comb[e] = (comb.get(e, 0) + w_t * w_s) % P
        combined_counts[key] = comb

    # DP
    from collections import defaultdict

    # keys: (used, prev_size, parity, even_count)
    all_states = {}
    used_keys = [[] for _ in range(max_edges + 1)]  # index by used
    init_key = (0, 1, 0, 1)  # used, prev_size, parity (prev layer index), even_count (including vertex 1)
    all_states[init_key] = {0: 1}
    used_keys[0].append(init_key)

    for used in range(0, N - 1):
        cur_keys = used_keys[used]
        if not cur_keys:
            continue
        for key in cur_keys:
            val_dict = all_states[key]
            _, prev_size, parity, even_count = key
            max_cur = N - 1 - used
            for cur_size in range(1, max_cur + 1):
                parity_new = parity ^ 1
                even_count_new = even_count + cur_size if parity_new == 0 else even_count
                if even_count_new > N // 2:
                    continue
                # prune if even_count_new + remaining vertices cannot reach N/2
                if even_count_new + (N - 1 - (used + cur_size)) < N // 2:
                    continue
                factor_label = invfact[cur_size]
                combined = combined_counts[(prev_size, cur_size)]
                new_key = (used + cur_size, cur_size, parity_new, even_count_new)
                new_dict = all_states.get(new_key)
                if new_dict is None:
                    new_dict = {}
                    all_states[new_key] = new_dict
                    used_keys[used + cur_size].append(new_key)
                for e_val, ways_val in val_dict.items():
                    for edges_add, ways_add in combined.items():
                        e2 = e_val + edges_add
                        if e2 > max_edges:
                            continue
                        add_val = ways_val * ways_add % P * factor_label % P
                        new_dict[e2] = (new_dict.get(e2, 0) + add_val) % P

    ans = [0] * (max_edges + 1)
    target_even = N // 2
    final_used = N - 1
    for key in used_keys[final_used]:
        _, _, _, even_count = key
        if even_count != target_even:
            continue
        for e, ways in all_states[key].items():
            ans[e] = (ans[e] + ways) % P

    mult = fact[N - 1]
    for e in range(N - 1, max_edges + 1):
        ans[e] = ans[e] * mult % P

    out = ' '.join(str(ans[e]) for e in range(N - 1, max_edges + 1))
    print(out)

if __name__ == "__main__":
    threading.Thread(target=solve).start()
