import sys

def solve():
    input = sys.stdin.readline
    N, X = map(int, input().split())
    items = []
    for _ in range(N):
        v, a, c = map(int, input().split())
        items.append((c, v, a))  # (calorie, vitamin type, amount)

    # Maintain list of non‑dominated states: (cal, v1, v2, v3)
    states = [(0, 0, 0, 0)]

    for cal_i, vtype, amt in items:
        new_states = []
        for cal, v1, v2, v3 in states:
            nc = cal + cal_i
            if nc > X:
                continue
            nv1 = v1
            nv2 = v2
            nv3 = v3
            if vtype == 1:
                nv1 += amt
            elif vtype == 2:
                nv2 += amt
            else:  # vtype == 3
                nv3 += amt
            new_states.append((nc, nv1, nv2, nv3))

        # Merge new states into current states with pruning
        for s in new_states:
            # Check if s is dominated by any existing state
            dominated = False
            for r in states:
                if r[0] <= s[0] and r[1] >= s[1] and r[2] >= s[2] and r[3] >= s[3]:
                    dominated = True
                    break
            if dominated:
                continue
            # Remove any existing state dominated by s
            new_list = []
            for r in states:
                if not (s[0] <= r[0] and s[1] >= r[1] and s[2] >= r[2] and s[3] >= r[3]):
                    new_list.append(r)
            new_list.append(s)
            states = new_list

    # Find maximum possible minimum vitamin intake
    ans = 0
    for cal, v1, v2, v3 in states:
        if cal <= X:
            m = min(v1, v2, v3)
            if m > ans:
                ans = m
    print(ans)

