def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = data[1].strip()
    L = len(A)
    # compute root original value
    bits = [int(ch) for ch in A]
    while len(bits) > 1:
        nb = []
        for i in range(0, len(bits), 3):
            a, b, c = bits[i], bits[i+1], bits[i+2]
            nb.append((a + b + c) >= 2)
        bits = nb
    root_val = bits[0]  # 0 or 1

    # dp for each leaf
    dp = []
    for ch in A:
        if ch == '0':
            dp.append((0, 1))  # (to make 0, to make 1)
        else:
            dp.append((1, 0))
    size = L
    INF = 10 ** 9
    while size > 1:
        new_dp = []
        for i in range(0, size, 3):
            d0a, d1a = dp[i]
            d0b, d1b = dp[i+1]
            d0c, d1c = dp[i+2]
            best0 = INF
            best1 = INF
            # iterate over 8 assignments of 3 bits (1 means child chosen as 1)
            for mask in range(8):
                bits_mask = [(mask >> k) & 1 for k in range(3)]
                cost = 0
                if bits_mask[0]:
                    cost += d1a
                else:
                    cost += d0a
                if bits_mask[1]:
                    cost += d1b
                else:
                    cost += d0b
                if bits_mask[2]:
                    cost += d1c
                else:
                    cost += d0c
                ones = bits_mask[0] + bits_mask[1] + bits_mask[2]
                if ones <= 1:  # at least two zeros => majority 0
                    if cost < best0:
                        best0 = cost
                if ones >= 2:  # at least two ones => majority 1
                    if cost < best1:
                        best1 = cost
            new_dp.append((best0, best1))
        dp = new_dp
        size //= 3
    final_dp0, final_dp1 = dp[0]
    if root_val == 0:
        print(final_dp1)
    else:
        print(final_dp0)

