import sys
from collections import deque

def solve() -> None:
    input = sys.stdin.readline
    N = int(input())
    adj_out = [dict() for _ in range(N)]   # node -> {char: list of targets}
    adj_in  = [dict() for _ in range(N)]   # node -> {char: list of sources}
    for i in range(N):
        line = input().strip()
        for j, ch in enumerate(line):
            if ch != '-':
                adj_out[i].setdefault(ch, []).append(j)
                adj_in[j].setdefault(ch, []).append(i)

    INF = -1
    dist_even = [[INF]*N for _ in range(N)]
    dist_odd  = [[INF]*N for _ in range(N)]

    # Multi-source BFS for even terminals (p,p)
    q = deque()
    for p in range(N):
        dist_even[p][p] = 0
        q.append((p,p))
    while q:
        u, v = q.popleft()
        d = dist_even[u][v]
        # predecessors: u' -> u, v -> v'  with same label
        for ch, u_list in adj_in[u].items():
            v_list = adj_out[v].get(ch, [])
            if not v_list:
                continue
            for pu in u_list:
                for pv in v_list:
                    if dist_even[pu][pv] == INF:
                        dist_even[pu][pv] = d + 1
                        q.append((pu,pv))

    # Multi-source BFS for odd terminals (u,v) where edge u->v exists
    q = deque()
    for u in range(N):
        for ch, v_list in adj_out[u].items():
            for v in v_list:
                dist_odd[u][v] = 0
                q.append((u,v))
    while q:
        u, v = q.popleft()
        d = dist_odd[u][v]
        for ch, u_list in adj_in[u].items():
            v_list = adj_out[v].get(ch, [])
            if not v_list:
                continue
            for pu in u_list:
                for pv in v_list:
                    if dist_odd[pu][pv] == INF:
                        dist_odd[pu][pv] = d + 1
                        q.append((pu,pv))

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            if i == j:
                row.append('0')
                continue
            best = None
            de = dist_even[i][j]
            do = dist_odd[i][j]
            if de != INF:
                best = 2*de
            if do != INF:
                val = 2*do + 1
                if best is None or val < best:
                    best = val
            row.append(str(best) if best is not None else '-1')
        out_lines.append(' '.join(row))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()
