import heapq

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    M = next(it)
    X = next(it)

    g0 = [[] for _ in range(N + 1)]
    g1 = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = next(it)
        v = next(it)
        g0[u].append(v)   # original orientation
        g1[v].append(u)   # reversed orientation (edge v->u becomes u->v)

    INF = 10 ** 30
    dist0 = [INF] * (N + 1)
    dist1 = [INF] * (N + 1)
    dist0[1] = 0
    pq = [(0, 1, 0)]  # (cost, node, parity)

    while pq:
        d, v, p = heapq.heappop(pq)
        if p == 0:
            if d != dist0[v]:
                continue
        else:
            if d != dist1[v]:
                continue

        if v == N:
            # we can break early if both parity distances are finalized
            # but we keep processing to ensure minimal
            pass

        # flip orientation
        nd = d + X
        if p == 0:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(pq, (nd, v, 1))
        else:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(pq, (nd, v, 0))

        # move along edges of current orientation
        if p == 0:
            for to in g0[v]:
                nd = d + 1
                if nd < dist0[to]:
                    dist0[to] = nd
                    heapq.heappush(pq, (nd, to, 0))
        else:
            for to in g1[v]:
                nd = d + 1
                if nd < dist1[to]:
                    dist1[to] = nd
                    heapq.heappush(pq, (nd, to, 1))

    ans = dist0[N] if dist0[N] < dist1[N] else dist1[N]
    print(ans)

if __name__ == "__main__":
