import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    X = int(next(it))
    U = [0]*N
    D = [0]*N
    for i in range(N):
        U[i] = int(next(it))
        D[i] = int(next(it))
    S = sum(U[i] + D[i] for i in range(N))
    M = min(U[i] + D[i] for i in range(N))
    def feasible(H: int) -> bool:
        l = H - D[0]
        if l < 0:
            l = 0
        r = U[0]
        if r > H:
            r = H
        if l > r:
            return False
        low, high = l, r
        for i in range(1, N):
            l = H - D[i]
            if l < 0:
                l = 0
            r = U[i]
            if r > H:
                r = H
            if l > r:
                return False
            new_low = l
            if low - X > new_low:
                new_low = low - X
            new_high = r
            if high + X < new_high:
                new_high = high + X
            if new_low > new_high:
                return False
            low, high = new_low, new_high
        return True
    lo, hi = 0, M
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    ans = S - N * best
    print(ans)

if __name__ == "__main__":
    solve()
