    order = []
    stack = [root]
    parent[root] = -1
    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            stack.append(to)

    ret = [0] * (NK + 1)
    impossible = False

    for v in reversed(order):
        counter = {}
        for to in adj[v]:
            if to == parent[v]:
                continue
            l = ret[to]
            if l == 0:
                continue
            needed = K - 1 - l
            if needed in counter and counter[needed] > 0:
                counter[needed] -= 1
                if counter[needed] == 0:
                    del counter[needed]
            else:
                counter[l] = counter.get(l, 0) + 1
        if impossible:
            break
        if not counter:
            # no open child paths, start new path upward
            ret[v] = 1
        elif len(counter) == 1:
            rem, cnt = next(iter(counter.items()))
            if cnt != 1:
                impossible = True
                break
            new_len = rem + 1
            if new_len == K:
                ret[v] = 0
            elif new_len < K:
                ret[v] = new_len
            else:
                impossible = True
                break
        else:
            impossible = True
            break

