    P = len(paths)
    edge_to_paths = [[] for _ in range(M)]
    for pi, p in enumerate(paths):
        for ei in p:
            edge_to_paths[ei].append(pi)

    # sort edges by coverage
    edge_order = sorted(range(M), key=lambda e: len(edge_to_paths[e]), reverse=True)

    # memoization dictionary
    from functools import lru_cache

    def feasible(d):
        init_R = [d]*P
        @lru_cache(maxsize=None)
        def dfs(idx, sel, R):
            if sel > K:
                return False
            if sel + (M - idx) < K:
                return False
            if idx == M:
                if sel != K:
                    return False
                for r in R:
                    if r > 0:
                        return False
                return True
            e = edge_order[idx]
            # try include
            if sel < K:
                R_list = list(R)
                for pi in edge_to_paths[e]:
                    if R_list[pi] > 0:
                        R_list[pi] -= 1
                R_tuple = tuple(R_list)
                if dfs(idx+1, sel+1, R_tuple):
                    return True
            # try skip
            if dfs(idx+1, sel, R):
                return True
            return False
        return dfs(0, 0, tuple(init_R))

    # binary search for max d
    lo, hi = 0, L_min
    ans = 0
    while lo <= hi:
        mid = (lo+hi)//2
        if feasible(mid):
            ans = mid
            lo = mid+1
        else:
            hi = mid-1
    print(ans)

if __name__ == "__main__":
    main()
