    # Prefix sums S[0..N]
    S = [0] * (N + 1)
    for i in range(1, N + 1):
        S[i] = (S[i-1] + A[i-1]) % MOD

    # Precompute factorials and inverse factorials for binomial coefficients
    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact = [1] * (K + 1)
    invfact[K] = pow(fact[K], MOD-2, MOD)
    for i in range(K, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    # pref_pow[p][i] = sum_{j=0}^{i} S[j]^p
    pref_pow = [[0] * (N + 1) for _ in range(K + 1)]
    # Initialize for i=0
    for p in range(K + 1):
        val = 1 if p == 0 else 0  # S[0]^p
        pref_pow[p][0] = val

    for i in range(1, N + 1):
        for p in range(K + 1):
            if p == 0:
                val = 1
            else:
                val = pow(S[i], p, MOD)
            pref_pow[p][i] = (pref_pow[p][i-1] + val) % MOD

    ans = 0
    for t in range(K + 1):
        coeff = comb(K, t)
        if (K - t) & 1:
            coeff = (-coeff) % MOD
        # sum over r=1..N
        sum_t = 0
        for r in range(1, N + 1):
            # S[r]^t
            if t == 0:
                sr_t = 1
            else:
                sr_t = pow(S[r], t, MOD)
            sum_t = (sum_t + sr_t * pref_pow[K-t][r-1]) % MOD
        ans = (ans + coeff * sum_t) % MOD

    print(ans)

