import sys
from collections import deque

def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1; v -= 1
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * N
    comps = []

    for s in range(N):
        if visited[s]:
            continue
        q = deque([s])
        visited[s] = True
        cnt0, cnt1 = 1, 0
        color = {s:0}
        while q:
            u = q.popleft()
            cu = color[u]
            for w in adj[u]:
                if not visited[w]:
                    visited[w] = True
                    color[w] = cu ^ 1
                    if color[w] == 0:
                        cnt0 += 1
                    else:
                        cnt1 += 1
                    q.append(w)
                else:
                    # graph is bipartite; no conflict
                    pass
        comps.append((cnt0, cnt1))

    full_mask = (1 << (N + 1)) - 1
    mask = 1  # only sum 0 reachable

    for a, b in comps:
        mask = ((mask << a) | (mask << b)) & full_mask

    half = N // 2
    best_dist = N + 1
    best_parity = 0
    for A in range(N + 1):
        if (mask >> A) & 1:
            dist = abs(A - half)
            if dist < best_dist:
                best_dist = dist
                best_parity = A & 1
            elif dist == best_dist:
                if A & 1:  # prefer odd if possible
                    best_parity = 1

    # compute product parity
    if N % 2 == 1:
        prod_parity = 0  # even always
    else:
        prod_parity = best_parity  # since B parity = best_parity
    moves_parity = prod_parity ^ (M & 1)
    if moves_parity:
        print("Aoki")
    else:
        print("Takahashi")

if __name__ == "__main__":
