import sys

def mat_mult(A, B, mod):
    n = len(A)
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ri = res[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ri[j] = (Ri[j] + aik * Bk[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = mat
    while exp:
        if exp & 1:
            res = mat_mult(res, base, mod)
        base = mat_mult(base, base, mod)
        exp >>= 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = [[int(next(it)) for _ in range(N)] for _ in range(N)]
    K = sum(1 for i in range(N) for j in range(N) if A[i][j]==0)
    if p == 2:
        # Build M
        M = [[0]*N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                if A[i][j]==0:
                    M[i][j] = 1
                else:
                    M[i][j] = A[i][j] & 1
        Mpow = mat_pow(M, 2, 2)  # p=2
        out = []
        for i in range(N):
            out.append(' '.join(str(x) for x in Mpow[i]))
        sys.stdout.write('\n'.join(out))
        return
    # General case p > 2
    # Build fixed matrix F
    F = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j]!=0:
                F[i][j] = A[i][j] % p
    # Compute F^p mod p
    Fpow = mat_pow(F, p, p)
    sign = 1 if K%2==0 else (p-1)
    # Base result
    result = [[(Fpow[i][j]*sign)%p for j in range(N)] for i in range(N)]
    var = [1 if A[i][i]==0 else 0 for i in range(N)]
    # Add contributions from variable self-loops with one fixed edge
    for i in range(N):
        for j in range(N):
            c = F[i][j]
            if c==0:
                continue
            add = (c * (var[i] + var[j])) % p
            add = (add * sign) % p
            result[i][j] = (result[i][j] + add) % p
    out = []
    for i in range(N):
        out.append(' '.join(str(result[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()
