        found = False
        for k in range(1, 2000):
            p = k * N + 1
            if p > 10**18:
                break
            if is_prime(p):
                # factor N and k
                fac_set = set()
                factor(N, fac_set)
                factor(k, fac_set)
                # find primitive root modulo p
                g = 2
                while g < p:
                    ok = True
                    for q in fac_set:
                        if pow(g, (p - 1) // q, p) == 1:
                            ok = False
                            break
                    if ok:
                        break
                    g += 1
                # compute A
                A = pow(g, k, p)
                out_lines.append(f"{A} {p}")
                found = True
                break
        if not found:
            # fallback: use large A, M=1 for N=1 only but here not
            out_lines.append("2 1")
    sys.stdout.write("\n".join(out_lines))

