    for p in small_primes:
        if n % p == 0:
            return n == p
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    # bases for deterministic test up to 2^64
    bases = [2, 325, 9375, 28178, 450775, 9780504, 1795265022]
    for a in bases:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

# Pollard's Rho
def pollard_rho(n: int) -> int:
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    while True:
        c = random.randrange(1, n-1)
        f = lambda x: (pow(x, 2, n) + c) % n
        x, y, d = 2, 2, 1
        while d == 1:
            x = f(x)
            y = f(f(y))
            d = math.gcd(abs(x - y), n)
        if d != n:
            return d

def factor(n: int, res: list):
    if n == 1:
        return
    if is_prime(n):
        res.append(n)
        return
    d = pollard_rho(n)
    factor(d, res)
    factor(n // d, res)

def get_factors(n: int):
    res = []
    factor(n, res)
    res.sort()
    return res

def get_divisors_from_factors(factors):
    # factors is list of primes (possibly repeated)
    # build dictionary of primes to exponents
    d = {}
    for p in factors:
        d[p] = d.get(p, 0) + 1
    primes = list(d.items())
    divs = [1]
    for p, e in primes:
        cur = []
        pw = 1
        for _ in range(e):
            pw *= p
            for val in divs:
                cur.append(val * pw)
        divs += cur
    divs.sort()
    return divs

def solve_case(N):
    if N == 1:
        return (2, 1)  # any works
    # find prime p = N*k + 1
    p = None
    # try small k first
    for k in range(1, 2000):
        cand = N * k + 1
        if cand > 10**18:
            break
        if is_prime(cand):
            p = cand
            break
    if p is None:
        # fallback random attempts
        while True:
            k = random.randint(1, 10**6)
            cand = N * k + 1
            if cand > 10**18:
                continue
            if is_prime(cand):
                p = cand
                break
    # factor p-1
    pf_p_minus1 = get_factors(p - 1)
    prime_set_p_minus1 = set(pf_p_minus1)
    # factor N to get divisors
    pf_N = get_factors(N)
    divisors = get_divisors_from_factors(pf_N)
    # try random a
    for _ in range(30):
        a = random.randrange(2, p)
        if pow(a, N, p) != 1:
            continue
        ok = True
        for d in divisors:
            if d == N:
                continue
            if pow(a, d, p) == 1:
                ok = False
                break
        if ok:
            return (a, p)
    # as a fallback, use primitive root approach
    # find primitive root g
    g = 2
    while True:
        ok = True
        for q in prime_set_p_minus1:
            if pow(g, (p - 1) // q, p) == 1:
                ok = False
                break
        if ok:
            break
        g += 1
    a = pow(g, (p - 1) // N, p)
    return (a, p)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        a, m = solve_case(N)
        out_lines.append(f"{a} {m}")
    sys.stdout.write("\n".join(out_lines))

