def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    V = N * 2  # each variable and its negation
    g = [[] for _ in range(V)]
    rg = [[] for _ in range(V)]

    def add_edge(u, v):
        g[u].append(v)
        rg[v].append(u)

    # adjacency clauses: not both true
    for i in range(N):
        ni = (i + 1) % N
        # x[i] -> not x[ni]
        add_edge(2 * i, 2 * ni + 1)
        # x[ni] -> not x[i]
        add_edge(2 * ni, 2 * i + 1)

    # zero clauses: x[i-1] or x[i]
    for i in range(N):
        if A[i] == 0:
            pi = (i - 1 + N) % N
            # not x[pi] -> x[i]
            add_edge(2 * pi + 1, 2 * i)
            # not x[i] -> x[pi]
            add_edge(2 * i + 1, 2 * pi)

    visited = [False] * V
    order = []

    def dfs(u):
        stack = [(u, 0)]
        while stack:
            node, state = stack.pop()
            if state == 0:
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, 1))
                for v in g[node]:
                    if not visited[v]:
                        stack.append((v, 0))
            else:
                order.append(node)

    for i in range(V):
        if not visited[i]:
            dfs(i)

    comp = [-1] * V
    def rdfs(u, label):
        stack = [u]
        while stack:
            node = stack.pop()
            if comp[node] != -1:
                continue
            comp[node] = label
            for v in rg[node]:
                if comp[v] == -1:
                    stack.append(v)

    label = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, label)
            label += 1

    ok = True
    for i in range(N):
        if comp[2 * i] == comp[2 * i + 1]:
            ok = False
            break

    print("Yes" if ok else "No")

