import sys

MOD = 998244353

def sieve(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            step = i
            for j in range(i * i, limit + 1, step):
                is_prime[j] = False
    return primes

def factorize(n, primes):
    res = {}
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            res[p] = e
    if n > 1:
        res[n] = 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N - 1)]

    primes_list = sieve(1000)
    prime_to_B = {}
    for idx, val in enumerate(A):
        facs = factorize(val, primes_list)
        for p, e in facs.items():
            if p not in prime_to_B:
                prime_to_B[p] = [0] * (N - 1)
            prime_to_B[p][idx] = e

    ans = 1
    for p, B in prime_to_B.items():
        Hmax = sum(B)
        if Hmax == 0:
            continue  # contributes 1
        # precompute powers of p up to Hmax
        pow_p = [1] * (Hmax + 1)
        for h in range(1, Hmax + 1):
            pow_p[h] = pow_p[h - 1] * p % MOD

        # initial dp: for each starting height h, weight = p^h
        dp = pow_p[:]  # copy

        for step in B:
            if step == 0:
                # multiply each dp[h] by p^h
                mul = pow_p
                for h in range(Hmax + 1):
                    dp[h] = dp[h] * mul[h] % MOD
            else:
                new_dp = [0] * (Hmax + 1)
                step_val = step
                mul = pow_p
                for h in range(Hmax + 1):
                    val = dp[h]
                    if val == 0:
                        continue
                    # from h-step to h
                    if h - step_val >= 0:
                        new_dp[h] = (new_dp[h] + val * mul[h]) % MOD
                    # from h+step to h
                    if h + step_val <= Hmax:
                        new_dp[h] = (new_dp[h] + val * mul[h]) % MOD
                dp = new_dp

        total = sum(dp) % MOD
        ans = ans * total % MOD

    print(ans % MOD)

