                        y = x + e
                        if y <= max_exp:
                            newdp[y] = (newdp[y] + val * r_pow[y]) % MOD
                        if x >= e:
                            y = x - e
                            if y >= 1:
                                newdp[y] = (newdp[y] + val * r_pow[y]) % MOD
            dp_pos = newdp
        positive_sum = sum(dp_pos) % MOD

        contrib = (total_sum - positive_sum) % MOD
        result = result * contrib % MOD

    print(result)

def main():
    solve()

threading.Thread(target=main).start()
