import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    A = [int(next(it)) for _ in range(n)]
    B = [int(next(it)) for _ in range(n)]
    C = [int(next(it)) for _ in range(n)]

    typeA = []  # indices where A[i]==1 and B[i]==0
    typeB = []  # indices where A[i]==0 and B[i]==1
    cur = 0  # current weight sum of A
    for i in range(n):
        if A[i]:
            cur += C[i]
        if A[i] != B[i]:
            if A[i] == 1:
                typeA.append(i)
            else:
                typeB.append(i)

    # Order: typeA descending C, then typeB ascending C
    order = sorted(typeA, key=lambda i: -C[i]) + sorted(typeB, key=lambda i: C[i])

    total_cost = 0
    for idx in order:
        if A[idx] == 1:
            cur -= C[idx]
            A[idx] = 0
        else:
            cur += C[idx]
            A[idx] = 1
        total_cost += cur

    print(total_cost)

if __name__ == "__main__":
    solve()
