import sys
sys.setrecursionlimit(1 << 25)

MOD = 998244353

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.parity = [0]*n  # parity to parent
    def find(self, x):
        if self.parent[x]==x:
            return x,0
        r,p = self.find(self.parent[x])
        self.parent[x] = r
        self.parity[x] ^= p
        return self.parent[x], self.parity[x]
    def union(self, x, y, w):  # value(x) XOR value(y) = w
        rx,px = self.find(x)
        ry,py = self.find(y)
        if rx==ry:
            return (px ^ py) == w
        # merge rx into ry
        self.parent[rx] = ry
        # set parity[rx] such that:
        # value(rx) ^ value(ry) = px ^ py ^ w
        self.parity[rx] = px ^ py ^ w
        return True

def solve():
    it = iter(sys.stdin.read().strip().split())
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        H = int(next(it)); W = int(next(it))
        grid = [list(next(it).strip()) for _ in range(H)]
        n = H + W
        dsu = DSU(n)
        fixed = [-1]*n  # fixed value for node if known
        ok = True
        for i in range(H):
            for j in range(W):
                c = grid[i][j]
                if c == 'A':
                    # set row i and col j to 1
                    if fixed[i] == -1:
                        fixed[i] = 1
                    elif fixed[i] != 1:
                        ok = False
                    if fixed[H+j] == -1:
                        fixed[H+j] = 1
                    elif fixed[H+j] != 1:
                        ok = False
                else:  # B
                    if not dsu.union(i, H+j, 1):
                        ok = False
        if not ok:
            out_lines.append("0")
            continue
        # propagate fixed values
        root_fixed = [-1]*n
        for node in range(n):
            if fixed[node] != -1:
                r, p = dsu.find(node)
                val_root = fixed[node] ^ p
                if root_fixed[r] == -1:
                    root_fixed[r] = val_root
                elif root_fixed[r] != val_root:
                    ok = False
                    break
        if not ok:
            out_lines.append("0")
            continue
        cnt = 0
        for i in range(n):
            if dsu.parent[i]==i:
                if root_fixed[i]==-1:
                    cnt += 1
        ans = pow(2, cnt, MOD)
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
